INSERT INTO `es_parameters` (`param_key`,`param_value`,`label`,`unit`,`description`) VALUES
('critical_cover_days',7,'Batas stok kritis','hari','Stok dianggap kritis bila cukup untuk <= nilai ini (berdasarkan kecepatan jual 30 hari).'),
('low_cover_days',14,'Batas stok rendah','hari','Stok rendah bila cukup untuk <= nilai ini.'),
('overstock_cover_days',120,'Batas stok berlebih','hari','Stok berlebih bila cukup untuk >= nilai ini.'),
('dead_stock_days',45,'Batas dead stock','hari','Tidak ada penjualan selama >= nilai ini dengan stok tersisa.'),
('target_cover_days',30,'Target cakupan stok setelah restock','hari','Dipakai menghitung saran jumlah restock.'),
('default_lead_time_days',7,'Lead time bawaan','hari','Dipakai bila belum ada penawaran supplier.'),
('unpaid_hours_limit',24,'Batas pembayaran order','jam','Order belum dibayar melebihi batas ini diberi peringatan.'),
('ship_sla_hours',48,'SLA pengiriman setelah dibayar','jam','Order lunas belum dikirim melebihi batas ini melanggar SLA.'),
('shipped_followup_hours',168,'Batas tindak lanjut paket terkirim','jam','Paket berstatus dikirim tanpa pembaruan melebihi batas ini.'),
('approval_age_days',3,'Batas persetujuan tertunda','hari','Persetujuan dokumen pending melebihi batas ini diingatkan.'),
('kms_request_age_days',7,'Batas permintaan pengetahuan terbuka','hari','Permintaan KMS terbuka melebihi batas ini dieskalasi.'),
('kms_stale_days',180,'Batas artikel KMS usang','hari','Artikel terbit yang tidak diperbarui melebihi batas ini dianggap usang.'),
('pace_gap_alert_pct',-15,'Batas selisih laju target','%','Selisih pencapaian vs laju ideal (poin persen) yang memicu peringatan MIS.'),
('wow_drop_alert_pct',-20,'Batas penurunan omzet mingguan','%','Penurunan omzet 7 hari vs 7 hari sebelumnya.'),
('cancel_rate_alert_pct',15,'Batas tingkat pembatalan','%','Persentase order dibatalkan 30 hari.'),
('concentration_alert_pct',40,'Batas ketergantungan satu produk','%','Porsi omzet 30 hari dari produk teratas.'),
('low_margin_pct',15,'Batas margin tipis','%','Margin kotor terhadap penawaran supplier terbaik.'),
('high_value_order',1500000,'Nilai order tinggi','Rp','Order bernilai >= ini diprioritaskan.'),
('surge_trend_pct',40,'Batas lonjakan permintaan','%','Kenaikan laju jual 7 hari terhadap rata-rata 30 hari.'),
('decline_trend_pct',-40,'Batas penurunan permintaan','%','Penurunan laju jual 7 hari terhadap rata-rata 30 hari.'),
('supplier_ontime_min_pct',70,'Ketepatan waktu minimal supplier','%','Di bawah ini supplier ditandai berisiko.'),
('supplier_accept_min_pct',90,'Tingkat penerimaan minimal supplier','%','Di bawah ini kualitas supplier ditandai.'),
('low_rating',3.5,'Batas rating rendah','bintang','Rating rata-rata produk di bawah ini ditandai kualitas.'),
('dss_stale_days',7,'Batas evaluasi DSS menggantung','hari','Evaluasi draf melebihi batas ini diingatkan.'),
('max_auto_actions_per_run',40,'Maks tindakan otomatis per siklus','aksi','Mencegah banjir tugas/notifikasi.'),
('event_driven_enabled',1,'Inferensi berbasis event aktif','0/1','1 = jalankan inferensi ringan setelah checkout, pembayaran, dan perubahan stok.');
INSERT INTO `es_rules` (`code`,`name`,`domain`,`subject_type`,`rule_kind`,`description`,`conditions`,`derives`,`severity`,`title_tpl`,`message_tpl`,`recommendation_tpl`,`actions`,`kms_keywords`,`cf`,`priority`,`is_active`,`is_system`) VALUES
('TPS-D-OUT','Stok habis padahal ada permintaan','TPS','variation','derive','Stok 0 sementara produk masih terjual dalam 30 hari terakhir.','{"all": [{"f": "stock", "op": "==", "v": 0}, {"f": "velocity_30d", "op": ">", "v": 0}]}','{"stock_risk": "out"}','medium',NULL,NULL,NULL,NULL,NULL,0.98,100,1,1),
('TPS-D-CRIT','Stok kritis','TPS','variation','derive','Stok hanya cukup untuk beberapa hari penjualan.','{"all": [{"f": "days_of_cover", "op": "<=", "v": {"param": "critical_cover_days"}}, {"f": "velocity_30d", "op": ">", "v": 0}, {"f": "stock", "op": ">", "v": 0}]}','{"stock_risk": "critical"}','medium',NULL,NULL,NULL,NULL,NULL,0.95,90,1,1),
('TPS-D-LOW','Stok rendah','TPS','variation','derive',NULL,'{"all": [{"f": "days_of_cover", "op": "<=", "v": {"param": "low_cover_days"}}, {"f": "velocity_30d", "op": ">", "v": 0}]}','{"stock_risk": "low"}','medium',NULL,NULL,NULL,NULL,NULL,0.9,80,1,1),
('TPS-D-DEAD','Dead stock','TPS','variation','derive','Tidak laku dalam waktu lama tetapi stok masih menumpuk.','{"all": [{"f": "days_since_last_sale", "op": ">=", "v": {"param": "dead_stock_days"}}, {"f": "stock", "op": ">=", "v": 20}]}','{"stock_risk": "dead"}','medium',NULL,NULL,NULL,NULL,NULL,0.9,70,1,1),
('TPS-D-OVER','Stok berlebih','TPS','variation','derive',NULL,'{"all": [{"f": "days_of_cover", "op": ">=", "v": {"param": "overstock_cover_days"}}, {"f": "stock", "op": ">=", "v": 35}, {"f": "velocity_30d", "op": ">", "v": 0}]}','{"stock_risk": "overstock"}','medium',NULL,NULL,NULL,NULL,NULL,0.85,60,1,1),
('TPS-D-SURGE','Permintaan melonjak','TPS','variation','derive',NULL,'{"all": [{"f": "sales_trend_pct", "op": ">=", "v": {"param": "surge_trend_pct"}}, {"f": "sold_7d", "op": ">=", "v": 4}]}','{"demand_state": "surging"}','medium',NULL,NULL,NULL,NULL,NULL,0.85,60,1,1),
('TPS-D-DECLINE','Permintaan menurun','TPS','variation','derive',NULL,'{"all": [{"f": "sales_trend_pct", "op": "<=", "v": {"param": "decline_trend_pct"}}, {"f": "sold_prev_7d", "op": ">=", "v": 3}]}','{"demand_state": "declining"}','medium',NULL,NULL,NULL,NULL,NULL,0.8,60,1,1),
('TPS-I-RESTOCK-DSS','Restock mendesak: mulai evaluasi supplier (DSS)','CROSS','variation','inference','Stok kritis, ada >=2 penawaran, belum ada evaluasi: sistem membuat evaluasi DSS dan tugas.','{"all": [{"f": "stock_risk", "op": "in", "v": ["critical", "out"]}, {"f": "has_incoming_po", "op": "==", "v": 0}, {"f": "dss_has_approved_supplier", "op": "==", "v": 0}, {"f": "dss_has_open_evaluation", "op": "==", "v": 0}, {"f": "offer_count", "op": ">=", "v": 2}]}',NULL,'high','Restock mendesak: {product_name} ({variant_label})','Sisa stok {stock} unit hanya cukup ±{days_of_cover|n1} hari (laju jual {velocity_30d|n2}/hari). Belum ada PO masuk dan belum ada keputusan supplier.','Bandingkan {offer_count} penawaran aktif lewat DSS (SAW). Kebutuhan restock ±{suggested_restock_qty} unit untuk cakupan 30 hari; lead time terbaik ±{lead_time_days|int} hari.','[{"type": "dss_start_evaluation", "auto": true}, {"type": "oas_task", "auto": true, "assign_role": "admin", "priority": "high", "due_days": 1, "title": "Lengkapi evaluasi DSS: {product_name} ({variant_label})"}, {"type": "oas_notify", "auto": true, "roles": ["manager"]}]','restock,pengadaan',0.92,90,1,1),
('TPS-I-RESTOCK-PO','Restock mendesak: buat PO ke supplier terpilih DSS','CROSS','variation','inference','Menghubungkan keputusan DSS dengan tindakan pengadaan.','{"all": [{"f": "stock_risk", "op": "in", "v": ["critical", "out"]}, {"f": "has_incoming_po", "op": "==", "v": 0}, {"f": "dss_has_approved_supplier", "op": "==", "v": 1}]}',NULL,'high','Buat PO: {product_name} ({variant_label})','Stok {stock} unit (±{days_of_cover|n1} hari). Keputusan DSS #{dss_approved_evaluation_id} sudah menetapkan {dss_approved_supplier}, tetapi belum ada PO berjalan.','Terbitkan PO ke {dss_approved_supplier} sebanyak ±{suggested_restock_qty} unit. Lead time ±{lead_time_days|int} hari; pantau stok selama menunggu.','[{"type": "oas_task", "auto": true, "assign_role": "admin", "priority": "urgent", "due_days": 1, "title": "Buat PO ke {dss_approved_supplier}: {product_name} ({variant_label})"}, {"type": "oas_notify", "auto": true, "roles": ["manager", "admin"]}]','restock,purchase order',0.95,92,1,1),
('TPS-I-RESTOCK-NOOFFER','Restock mendesak tanpa penawaran supplier','CROSS','variation','inference',NULL,'{"all": [{"f": "stock_risk", "op": "in", "v": ["critical", "out"]}, {"f": "has_incoming_po", "op": "==", "v": 0}, {"f": "offer_count", "op": "==", "v": 0}]}',NULL,'high','Tidak ada penawaran supplier: {product_name} ({variant_label})','Stok {stock} unit (±{days_of_cover|n1} hari) tetapi tidak ada penawaran supplier aktif untuk variasi ini.','Minta penawaran dari minimal 2 supplier (kolom penawaran DSS), lalu jalankan evaluasi. Pertimbangkan membatasi penjualan sementara.','[{"type": "oas_task", "auto": true, "assign_role": "admin", "priority": "high", "due_days": 1, "title": "Cari penawaran supplier: {product_name}"}, {"type": "oas_notify", "auto": true, "roles": ["manager"]}]','pencarian supplier,pengadaan',0.9,88,1,1),
('TPS-I-RESTOCK-DSS-OPEN','Evaluasi DSS berjalan, stok kritis','CROSS','variation','inference',NULL,'{"all": [{"f": "stock_risk", "op": "in", "v": ["critical", "out"]}, {"f": "dss_has_open_evaluation", "op": "==", "v": 1}, {"f": "dss_has_approved_supplier", "op": "==", "v": 0}, {"f": "has_incoming_po", "op": "==", "v": 0}]}',NULL,'medium','Percepat evaluasi DSS: {product_name} ({variant_label})','Stok kritis ({stock} unit) sementara evaluasi supplier masih berstatus terbuka {dss_open_evaluation_age_days|int} hari.','Lengkapi skor kriteria (mis. SERVICE), hitung SAW, lalu setujui evaluasi agar PO dapat diterbitkan.','[{"type": "oas_notify", "auto": true, "roles": ["admin"]}]',NULL,0.85,80,1,1),
('TPS-I-INCOMING','PO dalam perjalanan untuk stok rendah','TPS','variation','inference',NULL,'{"all": [{"f": "stock_risk", "op": "in", "v": ["critical", "low", "out"]}, {"f": "has_incoming_po", "op": "==", "v": 1}]}',NULL,'info','PO sedang berjalan: {product_name} ({variant_label})','Stok {stock} unit rendah, namun {incoming_po_qty} unit sedang dipesan.','Pantau tanggal penerimaan PO; tidak perlu pengadaan baru.',NULL,NULL,0.8,40,1,1),
('TPS-I-SURGE-STOCK','Permintaan melonjak dengan stok menipis','CROSS','variation','inference',NULL,'{"all": [{"f": "demand_state", "op": "==", "v": "surging"}, {"f": "stock_risk", "op": "in", "v": ["critical", "low", "out"]}]}',NULL,'critical','Lonjakan permintaan, stok menipis: {product_name} ({variant_label})','Laju jual 7 hari naik {sales_trend_pct|pct} dari rata-rata 30 hari, sementara stok {stock} unit (±{days_of_cover|n1} hari).','Prioritaskan restock cepat ke supplier dengan lead time terpendek dan batasi promosi pada variasi ini sampai stok aman.','[{"type": "oas_notify", "auto": true, "roles": ["manager", "admin"]}]','restock',0.9,95,1,1),
('TPS-I-DEAD','Dead stock: rancang promosi','TPS','variation','inference',NULL,'{"all": [{"f": "stock_risk", "op": "==", "v": "dead"}]}',NULL,'medium','Dead stock: {product_name} ({variant_label})','Tidak ada penjualan {days_since_last_sale|int} hari terakhir, stok tertahan {stock} unit (nilai ±{price|rp}/unit).','Jalankan bundling atau diskon bertahap 10-20%, tampilkan di beranda, dan tahan pembelian ulang. Evaluasi ulang koleksi serupa.','[{"type": "oas_task", "auto": false, "assign_role": "staff", "priority": "medium", "due_days": 5, "title": "Susun promo dead stock: {product_name}"}]','promo,diskon',0.85,50,1,1),
('TPS-I-OVERSTOCK-DECLINE','Stok berlebih dan permintaan menurun','TPS','variation','inference',NULL,'{"all": [{"f": "stock_risk", "op": "==", "v": "overstock"}, {"f": "demand_state", "op": "==", "v": "declining"}]}',NULL,'medium','Stok berlebih & permintaan turun: {product_name} ({variant_label})','Stok {stock} unit setara ±{days_of_cover|int} hari penjualan sementara laju jual turun {sales_trend_pct|pct}.','Hentikan pengadaan, jalankan promosi, dan evaluasi apakah produk perlu di-rebranding atau dihentikan.',NULL,'promo,diskon',0.85,55,1,1),
('TPS-I-OVERSTOCK','Stok berlebih','TPS','variation','inference',NULL,'{"all": [{"f": "stock_risk", "op": "==", "v": "overstock"}]}',NULL,'low','Stok berlebih: {product_name} ({variant_label})','Stok {stock} unit setara ±{days_of_cover|int} hari penjualan (target ideal ±30 hari).','Tunda pembelian ulang dan pertimbangkan promosi ringan untuk mempercepat perputaran.',NULL,NULL,0.75,30,1,1),
('DSS-I-LOWMARGIN','Margin tipis terhadap penawaran supplier','DSS','variation','inference',NULL,'{"all": [{"f": "margin_pct", "op": "<=", "v": {"param": "low_margin_pct"}}, {"f": "sold_30d", "op": ">=", "v": 1}]}',NULL,'medium','Margin tipis: {product_name} ({variant_label})','Harga jual {price|rp} vs penawaran terbaik {best_offer_price|rp} dari {best_offer_supplier} memberi margin kotor hanya {margin_pct|pct}.','Negosiasi harga dengan supplier atau jalankan evaluasi DSS ulang; pertimbangkan penyesuaian harga jual.','[{"type": "dss_start_evaluation", "auto": false}]','margin,negosiasi supplier',0.85,45,1,1),
('DSS-I-EVAL-STALE','Evaluasi DSS menggantung','DSS','variation','inference',NULL,'{"all": [{"f": "dss_has_open_evaluation", "op": "==", "v": 1}, {"f": "dss_open_evaluation_age_days", "op": ">=", "v": {"param": "dss_stale_days"}}]}',NULL,'low','Evaluasi DSS tertunda: {product_name} ({variant_label})','Evaluasi supplier untuk variasi ini masih terbuka {dss_open_evaluation_age_days|int} hari.','Selesaikan penilaian dan setujui keputusan, atau batalkan bila tidak relevan.',NULL,NULL,0.8,35,1,1),
('TPS-I-CART-PRESSURE','Keranjang menahan stok tipis','TPS','variation','inference',NULL,'{"all": [{"f": "cart_qty", "op": ">=", "v": 2}, {"f": "stock", "op": "<=", "v": 5}]}',NULL,'low','Permintaan tertahan di keranjang: {product_name} ({variant_label})','{cart_qty} unit berada di keranjang pelanggan sementara stok hanya {stock} unit.','Percepat restock agar penjualan tidak hilang.',NULL,NULL,0.7,35,1,1),
('TPS-I-QUALITY','Keluhan kualitas produk','TPS','variation','inference',NULL,'{"all": [{"f": "rating_avg", "op": "<=", "v": {"param": "low_rating"}}, {"f": "review_count", "op": ">=", "v": 3}, {"f": "sold_30d", "op": ">=", "v": 5}]}',NULL,'high','Kualitas dikeluhkan: {product_name}','Rating rata-rata {rating_avg|n2} dari {review_count} ulasan, sementara masih terjual {sold_30d} unit/30 hari.','Tinjau ulasan, periksa kualitas batch dari supplier, dan pertimbangkan hold penjualan/komplain ke supplier.','[{"type": "oas_task", "auto": true, "assign_role": "staff", "priority": "high", "due_days": 3, "title": "Tinjau keluhan kualitas: {product_name}"}, {"type": "oas_notify", "auto": true, "roles": ["manager"]}]','kualitas,retur,quality control',0.85,75,1,1),
('TPS-I-UNPAID','Pesanan belum dibayar melewati batas','TPS','order','inference',NULL,'{"all": [{"f": "status", "op": "==", "v": "pending"}, {"f": "payment_status", "op": "==", "v": "pending"}, {"f": "age_hours", "op": ">=", "v": {"param": "unpaid_hours_limit"}}]}',NULL,'medium','Belum dibayar {age_hours|int} jam: {order_number}','Pesanan {order_number} ({buyer}, {total_price|rp}) menahan {units} unit stok tetapi belum dibayar.','Kirim pengingat pembayaran atau batalkan pesanan agar stok kembali tersedia.','[{"type": "oas_task", "auto": true, "assign_role": "staff", "priority": "medium", "due_days": 1, "title": "Follow up pembayaran {order_number}"}, {"type": "tps_cancel_unpaid_order", "auto": false}]','pembayaran',0.88,60,1,1),
('TPS-I-SHIP-SLA','Pesanan lunas melanggar SLA pengiriman','TPS','order','inference',NULL,'{"all": [{"f": "status", "op": "==", "v": "processing"}, {"f": "payment_status", "op": "==", "v": "paid"}, {"f": "age_hours", "op": ">=", "v": {"param": "ship_sla_hours"}}]}',NULL,'high','SLA pengiriman terlewat: {order_number}','Pesanan {order_number} ({buyer}) sudah lunas dan berumur {age_hours|int} jam, belum dikirim.','Kemas dan serahkan ke kurir hari ini; informasikan pelanggan bila ada kendala.','[{"type": "oas_task", "auto": true, "assign_role": "staff", "priority": "urgent", "due_days": 0, "title": "Kirim segera {order_number} (SLA terlewat)"}, {"type": "oas_notify", "auto": true, "roles": ["manager"]}]','sop pengemasan,pengiriman',0.92,85,1,1),
('TPS-I-SHIPPED-STUCK','Paket dikirim tanpa pembaruan','TPS','order','inference',NULL,'{"all": [{"f": "status", "op": "==", "v": "shipped"}, {"f": "idle_hours", "op": ">=", "v": {"param": "shipped_followup_hours"}}]}',NULL,'medium','Paket belum selesai: {order_number}','Pesanan {order_number} berstatus dikirim tanpa pembaruan selama {idle_hours|int} jam.','Lacak paket ke kurir dan hubungi pelanggan; ajukan klaim bila paket hilang.','[{"type": "oas_task", "auto": true, "assign_role": "staff", "priority": "high", "due_days": 1, "title": "Lacak paket {order_number}"}]','kurir,paket hilang',0.85,65,1,1),
('TPS-I-HIGHVALUE','Pesanan bernilai tinggi','TPS','order','inference',NULL,'{"all": [{"f": "total_price", "op": ">=", "v": {"param": "high_value_order"}}, {"f": "status", "op": "in", "v": ["pending", "processing"]}]}',NULL,'info','Order bernilai tinggi: {order_number}','Pesanan {order_number} bernilai {total_price|rp} dari {buyer}.','Prioritaskan pengemasan dan pastikan kualitas pengecekan barang.',NULL,NULL,0.7,30,1,1),
('OAS-I-OVERDUE-HIGH','Tugas prioritas tinggi terlambat','OAS','task','inference',NULL,'{"all": [{"f": "is_overdue", "op": "==", "v": 1}, {"f": "priority", "op": "in", "v": ["high", "urgent"]}]}',NULL,'high','Tugas terlambat: {title}','Tugas prioritas {priority} untuk {assignee} terlambat {overdue_days|int} hari.','Eskalasi ke manager, bantu hilangkan hambatan, atau alihkan tugas.','[{"type": "oas_notify", "auto": true, "roles": ["manager"]}]',NULL,0.9,70,1,1),
('OAS-I-OVERDUE','Tugas terlambat','OAS','task','inference',NULL,'{"all": [{"f": "is_overdue", "op": "==", "v": 1}, {"f": "priority", "op": "in", "v": ["low", "medium"]}]}',NULL,'low','Tugas terlambat: {title}','Tugas untuk {assignee} terlambat {overdue_days|int} hari.','Perbarui status atau tenggat tugas.',NULL,NULL,0.8,30,1,1),
('OAS-I-APPROVAL-STALE','Persetujuan dokumen tertunda','OAS','approval','inference',NULL,'{"all": [{"f": "age_days", "op": ">=", "v": {"param": "approval_age_days"}}]}',NULL,'medium','Persetujuan tertunda: {document_title}','Menunggu {approver} selama {age_days|int} hari.','Ingatkan approver atau delegasikan peninjauan.','[{"type": "oas_notify", "auto": true, "roles": ["manager", "admin"]}]',NULL,0.85,50,1,1),
('KMS-I-REQUEST-URGENT','Permintaan pengetahuan mendesak belum dijawab','KMS','knowledge_request','inference',NULL,'{"all": [{"f": "priority", "op": "in", "v": ["high", "urgent"]}, {"f": "age_days", "op": ">=", "v": 2}]}',NULL,'high','Permintaan pengetahuan mendesak: {title}','Permintaan prioritas {priority} terbuka {age_days|int} hari.','Tugaskan pakar internal untuk menulis artikel atau SOP.','[{"type": "oas_notify", "auto": true, "roles": ["manager"]}]',NULL,0.85,60,1,1),
('KMS-I-REQUEST-STALE','Permintaan pengetahuan menumpuk','KMS','knowledge_request','inference',NULL,'{"all": [{"f": "age_days", "op": ">=", "v": {"param": "kms_request_age_days"}}, {"f": "status", "op": "==", "v": "open"}]}',NULL,'low','Permintaan pengetahuan lama: {title}','Belum ditangani selama {age_days|int} hari.','Tetapkan penanggung jawab penulisan artikel.',NULL,NULL,0.75,30,1,1),
('DSS-I-SUP-LATE','Supplier sering terlambat','DSS','supplier','inference',NULL,'{"all": [{"f": "on_time_rate", "op": "<", "v": {"param": "supplier_ontime_min_pct"}}, {"f": "po_count", "op": ">=", "v": 2}]}',NULL,'medium','Ketepatan waktu rendah: {supplier_name}','On-time {on_time_rate|pct} dari {po_count} PO (rata-rata telat {avg_delay_days|n1} hari).','Negosiasikan SLA/penalti, tambah buffer lead time, atau diversifikasi ke supplier lain pada evaluasi DSS.',NULL,'evaluasi supplier,negosiasi supplier',0.85,55,1,1),
('DSS-I-SUP-QUALITY','Kualitas penerimaan supplier rendah','DSS','supplier','inference',NULL,'{"all": [{"f": "acceptance_rate", "op": "<", "v": {"param": "supplier_accept_min_pct"}}, {"f": "po_count", "op": ">=", "v": 1}]}',NULL,'medium','Penerimaan barang rendah: {supplier_name}','Hanya {acceptance_rate|pct} barang diterima tanpa penolakan dari {po_count} PO.','Perketat inspeksi penerimaan dan ajukan klaim/retur batch cacat.',NULL,'kualitas,quality control,evaluasi supplier',0.85,55,1,1),
('DSS-I-SUP-OFFERS','Penawaran supplier kedaluwarsa','DSS','supplier','inference',NULL,'{"all": [{"f": "offers_expired", "op": ">=", "v": 1}]}',NULL,'low','Penawaran kedaluwarsa: {supplier_name}','{offers_expired} penawaran sudah melewati masa berlaku.','Minta penawaran terbaru agar tetap dapat dipakai pada evaluasi.','[{"type": "oas_task", "auto": false, "assign_role": "admin", "priority": "low", "due_days": 5, "title": "Perbarui penawaran {supplier_name}"}]',NULL,0.8,30,1,1),
